```python
def path_match(pattern, text):
    tokens = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 < n:
                tokens.append(('lit', pattern[i + 1]))
                i += 2
            else:
                tokens.append(('lit', '\\'))
                i += 1
        elif c == '*':
            if i + 1 < n and pattern[i + 1] == '*':
                tokens.append(('dstar', None))
                i += 2
            else:
                tokens.append(('star', None))
                i += 1
        elif c == '?':
            tokens.append(('q', None))
            i += 1
        else:
            tokens.append(('lit', c))
            i += 1

    m = len(tokens)
    tlen = len(text)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def match(ti, si):
        if ti == m:
            return si == tlen
        kind, val = tokens[ti]
        if kind == 'lit':
            if si < tlen and text[si] == val:
                return match(ti + 1, si + 1)
            return False
        if kind == 'q':
            if si < tlen and text[si] != '/':
                return match(ti + 1, si + 1)
            return False
        if kind == 'star':
            if match(ti + 1, si):
                return True
            if si < tlen and text[si] != '/':
                return match(ti, si + 1)
            return False
        if kind == 'dstar':
            if match(ti + 1, si):
                return True
            if si < tlen:
                return match(ti, si + 1)
            return False
        return False

    return match(0, 0)
```

