            if i + 1 < n and pattern[i + 1] == '*':
                tokens.append(('dstar', None))
                i += 2
            else:
                tokens.append(('star', None))
                i += 1
        elif c == '?':
            tokens.append(('q', None))
            i += 1
        else:
            tokens.append(('lit', c))
            i += 1

    m = len(tokens)
    tlen = len(text)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def match(ti, si):
        if ti == m:
            return si == tlen
        kind, val = tokens[ti]
        if kind == 'lit':
