import re

def compare_versions(a, b):
    def parse(s):
        if not isinstance(s, str):
            raise ValueError("version must be a string")
        if s != s.strip() or any(c.isspace() for c in s):
            raise ValueError("whitespace not allowed")
        m = re.fullmatch(
            r'([0-9]+)\.([0-9]+)\.([0-9]+)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?',
            s
        )
        if not m:
            raise ValueError("invalid version format")
        major, minor, patch, pre, build = m.groups()
        nums = []
        for part in (major, minor, patch):
            if len(part) > 1 and part[0] == '0':
                raise ValueError("leading zero in version number")
            nums.append(int(part))
        pre_ids = None
        if pre is not None:
            pre_ids = pre.split('.')
            for ident in pre_ids:
                if not re.fullmatch(r'[0-9A-Za-z-]+', ident):
                    raise ValueError("invalid prerelease identifier")
                if ident.isdigit() and len(ident) > 1 and ident[0] == '0':
                    raise ValueError("leading zero in numeric prerelease identifier")
        if build is not None:
            for ident in build.split('.'):
                if not re.fullmatch(r'[0-9A-Za-z-]+', ident):
                    raise ValueError("invalid build identifier")
        return nums, pre_ids

    na, pa = parse(a)
    nb, pb = parse(b)

    for x, y in zip(na, nb):
        if x < y:
            return -1
        if x > y:
            return 1

    if pa is None and pb is None:
        return 0
    if pa is None:
        return 1
    if pb is None:
        return -1

    for x, y in zip(pa, pb):
        xd = x.isdigit()
        yd = y.isdigit()
        if xd and yd:
            xi, yi = int(x), int(y)
            if xi < yi:
                return -1
            if xi > yi:
                return 1
        elif xd and not yd:
            return -1
        elif not xd and yd:
            return 1
        else:
            if x < y:
                return -1
            if x > y:
                return 1

    if len(pa) < len(pb):
        return -1
    if len(pa) > len(pb):
        return 1
    return 0
```

